//! I8e — the RM API messages after `GSP_INIT_DONE`: `GSP_RM_ALLOC` (create an
//! object) and `GSP_RM_CONTROL` (a command on an object), plus the parameter
//! blocks the "golden image" step needs. Built and tested **only in SIMULARE**.
//!
//! Every offset and size here comes from `nvidia_rm570::rmapi`, generated by
//! bindgen from NVIDIA's MIT headers (open-gpu-kernel-modules 570.144:
//! `g_rpc-structures.h`, `nvos.h`, `cl0080.h`, `alloc_channel.h`,
//! `ctrl2080fifo.h`, `ctrl2080gpu.h`, `ctrl2080internal.h`, `ctrl90f1.h`),
//! through `core::mem::offset_of!` — nothing is counted by hand. The
//! independent check is `gpu_sim::fake_rm`, which parses the same bytes with
//! offsets written by hand from the headers.
//!
//! Which values go into which field: tinygrad `runtime/support/nv/ip.py`
//! (`init_golden_image`, `rpc_rm_alloc`, `promote_ctx`, MIT, commit
//! 9cf7829a6), read as a specification and re-written; nouveau `r535.c` (MIT)
//! for the general shape of the two RPCs. The values tinygrad found
//! empirically (channel `flags = 0x200320`, `internalFlags = 0x1a`, `cid = 3`,
//! the client handle `0xc1e00004`) are DEDUS: they worked for tinygrad on
//! GA102 + 570.144; nobody documents why.
//!
//! Nothing in this module touches the board: it only builds and parses bytes.

use alloc::vec::Vec;
use core::mem::{offset_of, size_of};

use gpu_core::error::{GpuError, GpuResult};
use nvidia_rm570::rmapi as r;

use super::{get_u32, get_u64, put_u32, put_u64};

/// Object classes (generated from the class headers).
pub mod class {
    use nvidia_rm570::rmapi as r;
    pub const ROOT: u32 = r::NV01_ROOT;
    pub const DEVICE: u32 = r::NV01_DEVICE_0;
    pub const SUBDEVICE: u32 = r::NV20_SUBDEVICE_0;
    pub const VASPACE: u32 = r::FERMI_VASPACE_A;
    pub const CHANNEL_GPFIFO: u32 = r::AMPERE_CHANNEL_GPFIFO_A;
    pub const COMPUTE: u32 = r::AMPERE_COMPUTE_B;
    pub const DMA_COPY: u32 = r::AMPERE_DMA_COPY_B;
    /// I9d: channel group (TSG) and context share (subcontext).
    pub const CHANNEL_GROUP: u32 = r::KEPLER_CHANNEL_GROUP_A;
    pub const CONTEXT_SHARE: u32 = r::FERMI_CONTEXT_SHARE_A;
}

/// Control commands (generated).
pub mod cmd {
    use nvidia_rm570::rmapi as r;
    pub const GET_DEVICE_INFO_TABLE: u32 = r::NV2080_CTRL_CMD_FIFO_GET_DEVICE_INFO_TABLE;
    pub const KGR_GET_CONTEXT_BUFFERS_INFO: u32 =
        r::NV2080_CTRL_CMD_INTERNAL_STATIC_KGR_GET_CONTEXT_BUFFERS_INFO;
    pub const PROMOTE_CTX: u32 = r::NV2080_CTRL_CMD_GPU_PROMOTE_CTX;
    pub const COPY_SERVER_RESERVED_PDES: u32 = r::NV90F1_CTRL_CMD_VASPACE_COPY_SERVER_RESERVED_PDES;
    /// I9e: on a channel; on a channel group.
    pub const WORK_SUBMIT_TOKEN: u32 = r::NVC36F_CTRL_CMD_GPFIFO_GET_WORK_SUBMIT_TOKEN;
    pub const TSG_SCHEDULE: u32 = r::NVA06C_CTRL_CMD_GPFIFO_SCHEDULE;
}

/// `NV2080_ENGINE_TYPE_GR0` (the graphics/compute engine).
pub const ENGINE_GR0: u32 = r::NV2080_ENGINE_TYPE_GR0;
/// `NV_MEMORY_DESC_PARAMS.addressSpace` for video memory (`ADDR_FBMEM`, as
/// tinygrad and RM's `memdescGetAddressSpace` use it; DEDUS from tinygrad).
pub const ADDR_SPACE_VIDMEM: u32 = 2;

/// `rpc_gsp_rm_alloc_v03_00` / `rpc_gsp_rm_control_v03_00` (generated offsets).
const ALLOC_HDR: usize = r::RPC_GSP_RM_ALLOC_PARAMS as usize;
const CONTROL_HDR: usize = r::RPC_GSP_RM_CONTROL_PARAMS as usize;

/// Payload of `GSP_RM_ALLOC`.
pub fn encode_alloc(
    h_client: u32,
    h_parent: u32,
    h_object: u32,
    h_class: u32,
    params: &[u8],
) -> Vec<u8> {
    let mut b = alloc::vec![0u8; ALLOC_HDR + params.len()];
    put_u32(&mut b, r::RPC_GSP_RM_ALLOC_HCLIENT as usize, h_client);
    put_u32(&mut b, r::RPC_GSP_RM_ALLOC_HPARENT as usize, h_parent);
    put_u32(&mut b, r::RPC_GSP_RM_ALLOC_HOBJECT as usize, h_object);
    put_u32(&mut b, r::RPC_GSP_RM_ALLOC_HCLASS as usize, h_class);
    put_u32(
        &mut b,
        r::RPC_GSP_RM_ALLOC_PARAMS_SIZE as usize,
        params.len() as u32,
    );
    b[ALLOC_HDR..].copy_from_slice(params);
    b
}

/// Payload of `GSP_RM_CONTROL`.
pub fn encode_control(h_client: u32, h_object: u32, command: u32, params: &[u8]) -> Vec<u8> {
    let mut b = alloc::vec![0u8; CONTROL_HDR + params.len()];
    put_u32(&mut b, r::RPC_GSP_RM_CONTROL_HCLIENT as usize, h_client);
    put_u32(&mut b, r::RPC_GSP_RM_CONTROL_HOBJECT as usize, h_object);
    put_u32(&mut b, r::RPC_GSP_RM_CONTROL_CMD as usize, command);
    put_u32(
        &mut b,
        r::RPC_GSP_RM_CONTROL_PARAMS_SIZE as usize,
        params.len() as u32,
    );
    b[CONTROL_HDR..].copy_from_slice(params);
    b
}

/// Checks GSP-RM's answer to an allocation: same header, status `NV_OK`.
/// A non-zero status is the RM error code (`nvstatuscodes.h`), returned as
/// `HardwareFault` — never treated as success.
pub fn check_alloc_reply(sent: &[u8], reply: &[u8]) -> GpuResult<Vec<u8>> {
    if reply.len() != sent.len() {
        return Err(GpuError::InvalidArgument(
            "RM_ALLOC: raspuns de alta lungime",
        ));
    }
    for o in [
        r::RPC_GSP_RM_ALLOC_HCLIENT,
        r::RPC_GSP_RM_ALLOC_HPARENT,
        r::RPC_GSP_RM_ALLOC_HOBJECT,
        r::RPC_GSP_RM_ALLOC_HCLASS,
    ] {
        if get_u32(reply, o as usize) != get_u32(sent, o as usize) {
            return Err(GpuError::InvalidArgument(
                "RM_ALLOC: raspunsul e pentru alt obiect",
            ));
        }
    }
    match get_u32(reply, r::RPC_GSP_RM_ALLOC_STATUS as usize) {
        0 => Ok(reply[ALLOC_HDR..].to_vec()),
        code => Err(GpuError::HardwareFault { code }),
    }
}

/// Checks GSP-RM's answer to a control and returns the parameters it filled.
pub fn check_control_reply(sent: &[u8], reply: &[u8]) -> GpuResult<Vec<u8>> {
    if reply.len() != sent.len() {
        return Err(GpuError::InvalidArgument(
            "RM_CONTROL: raspuns de alta lungime",
        ));
    }
    for o in [
        r::RPC_GSP_RM_CONTROL_HCLIENT,
        r::RPC_GSP_RM_CONTROL_HOBJECT,
        r::RPC_GSP_RM_CONTROL_CMD,
    ] {
        if get_u32(reply, o as usize) != get_u32(sent, o as usize) {
            return Err(GpuError::InvalidArgument(
                "RM_CONTROL: raspunsul e pentru alta comanda",
            ));
        }
    }
    match get_u32(reply, r::RPC_GSP_RM_CONTROL_STATUS as usize) {
        0 => Ok(reply[CONTROL_HDR..].to_vec()),
        code => Err(GpuError::HardwareFault { code }),
    }
}

/// `NV0000_ALLOC_PARAMETERS`: all zero, as tinygrad sends it (GSP-RM fills
/// in what it needs for an internal client).
pub fn root_params() -> Vec<u8> {
    alloc::vec![0u8; size_of::<r::NV0000_ALLOC_PARAMETERS>()]
}

/// `NV0080_ALLOC_PARAMETERS` with `hClientShare` = the client.
pub fn device_params(h_client_share: u32) -> Vec<u8> {
    let mut b = alloc::vec![0u8; size_of::<r::NV0080_ALLOC_PARAMETERS>()];
    put_u32(
        &mut b,
        offset_of!(r::NV0080_ALLOC_PARAMETERS, hClientShare),
        h_client_share,
    );
    b
}

/// `NV2080_ALLOC_PARAMETERS` (subdevice 0).
pub fn subdevice_params() -> Vec<u8> {
    alloc::vec![0u8; size_of::<r::NV2080_ALLOC_PARAMETERS>()]
}

/// `NV_VASPACE_ALLOCATION_PARAMETERS`: all defaults (zero), as tinygrad.
pub fn vaspace_params() -> Vec<u8> {
    alloc::vec![0u8; size_of::<r::NV_VASPACE_ALLOCATION_PARAMETERS>()]
}

/// `NV_MEMORY_DESC_PARAMS`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MemDesc {
    pub base: u64,
    pub size: u64,
    pub address_space: u32,
    pub cache_attrib: u32,
}

impl MemDesc {
    pub fn vidmem(base: u64, size: u64) -> Self {
        MemDesc {
            base,
            size,
            address_space: ADDR_SPACE_VIDMEM,
            cache_attrib: 0,
        }
    }
}

fn put_memdesc(b: &mut [u8], at: usize, m: &MemDesc) {
    put_u64(b, at + offset_of!(r::NV_MEMORY_DESC_PARAMS, base), m.base);
    put_u64(b, at + offset_of!(r::NV_MEMORY_DESC_PARAMS, size), m.size);
    put_u32(
        b,
        at + offset_of!(r::NV_MEMORY_DESC_PARAMS, addressSpace),
        m.address_space,
    );
    put_u32(
        b,
        at + offset_of!(r::NV_MEMORY_DESC_PARAMS, cacheAttrib),
        m.cache_attrib,
    );
}

/// What the driver supplies for the golden channel (tinygrad's values in
/// [`ChannelSetup::golden`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ChannelSetup {
    pub gpfifo_va: u64,
    pub gpfifo_entries: u32,
    pub h_vaspace: u32,
    pub userd_offset: u64,
    pub userd: MemDesc,
    pub instance: MemDesc,
    pub ramfc: MemDesc,
    pub mthdbuf: MemDesc,
    pub engine_type: u32,
    pub cid: u32,
    pub flags: u32,
    pub internal_flags: u32,
}

/// Values tinygrad uses for the golden channel (ip.py, `init_golden_image`
/// and `rpc_rm_alloc`). DEDUS: proven only by tinygrad running them.
pub mod golden_channel {
    pub const GPFIFO_ENTRIES: u32 = 32;
    pub const CID: u32 = 3;
    pub const FLAGS: u32 = 0x0020_0320;
    pub const INTERNAL_FLAGS: u32 = 0x1a;
    /// USERD lives right after the 32 GPFIFO entries in the same 4 KiB page.
    pub const USERD_OFFSET: u64 = 0x20 * 8;
    pub const USERD_SIZE: u64 = 0x20;
    pub const RAMFC_SIZE: u64 = 0x200;
    pub const INSTANCE_SIZE: u64 = 0x1000;
    pub const METHOD_BUFFER_SIZE: u64 = 0x5000;
}

impl ChannelSetup {
    /// The golden channel: GPFIFO + USERD in one 4 KiB page (`gpfifo_va` /
    /// `gpfifo_pa`), RAMFC = start of the 4 KiB instance block at `inst_pa`,
    /// method buffer at `mthd_pa`.
    pub fn golden(
        gpfifo_va: u64,
        gpfifo_pa: u64,
        h_vaspace: u32,
        inst_pa: u64,
        mthd_pa: u64,
    ) -> Self {
        use golden_channel as g;
        ChannelSetup {
            gpfifo_va,
            gpfifo_entries: g::GPFIFO_ENTRIES,
            h_vaspace,
            userd_offset: g::USERD_OFFSET,
            userd: MemDesc::vidmem(gpfifo_pa + g::USERD_OFFSET, g::USERD_SIZE),
            instance: MemDesc::vidmem(inst_pa, g::INSTANCE_SIZE),
            ramfc: MemDesc::vidmem(inst_pa, g::RAMFC_SIZE),
            mthdbuf: MemDesc::vidmem(mthd_pa, g::METHOD_BUFFER_SIZE),
            engine_type: ENGINE_GR0,
            cid: g::CID,
            flags: g::FLAGS,
            internal_flags: g::INTERNAL_FLAGS,
        }
    }
}

/// `NV_CHANNEL_ALLOC_PARAMS` (= `NV_CHANNELGPFIFO_ALLOCATION_PARAMETERS`).
pub fn channel_params(c: &ChannelSetup) -> GpuResult<Vec<u8>> {
    if c.gpfifo_entries < 2 || !c.gpfifo_entries.is_power_of_two() {
        return Err(GpuError::InvalidArgument(
            "canal: numarul de intrari GPFIFO nu e putere a lui 2",
        ));
    }
    if c.gpfifo_va == 0 || !c.gpfifo_va.is_multiple_of(0x1000) {
        return Err(GpuError::InvalidArgument(
            "canal: adresa GPFIFO lipsa sau nealiniata",
        ));
    }
    type C = r::NV_CHANNEL_ALLOC_PARAMS;
    let mut b = alloc::vec![0u8; size_of::<C>()];
    put_u64(&mut b, offset_of!(C, gpFifoOffset), c.gpfifo_va);
    put_u32(&mut b, offset_of!(C, gpFifoEntries), c.gpfifo_entries);
    put_u32(&mut b, offset_of!(C, flags), c.flags);
    put_u32(&mut b, offset_of!(C, hVASpace), c.h_vaspace);
    put_u64(&mut b, offset_of!(C, userdOffset), c.userd_offset); // [0]
    put_u32(&mut b, offset_of!(C, engineType), c.engine_type);
    put_u32(&mut b, offset_of!(C, cid), c.cid);
    put_memdesc(&mut b, offset_of!(C, instanceMem), &c.instance);
    put_memdesc(&mut b, offset_of!(C, userdMem), &c.userd);
    put_memdesc(&mut b, offset_of!(C, ramfcMem), &c.ramfc);
    put_memdesc(&mut b, offset_of!(C, mthdbufMem), &c.mthdbuf);
    put_u32(&mut b, offset_of!(C, internalFlags), c.internal_flags);
    Ok(b)
}

/// I9e: what the driver supplies for a working channel inside a channel
/// group (TSG). The ring and its USERD share one contiguous, mapped buffer
/// (ring first, USERD right after it, as tinygrad's `_new_gpu_fifo`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WorkChannelSetup {
    /// GPU VA / PA of the buffer holding the ring and then USERD.
    pub ring_va: u64,
    pub ring_pa: u64,
    pub entries: u32,
    /// The context share the channel runs in (I9d).
    pub ctxshare: u32,
    /// Instance block (RAMFC = its start) and method buffer, VRAM.
    pub inst_pa: u64,
    pub mthd_pa: u64,
    /// The error notifier's PA (only its low 32 bits travel, see below).
    pub notifier_pa: u64,
}

/// Values tinygrad uses for a working channel (`ops_nv.py`
/// `_new_gpu_fifo`, `ip.py` `rpc_rm_alloc`, MIT, commit 9cf7829a6). DEDUS.
pub mod work_channel {
    /// tinygrad: `userdMem.size = 0x400` for a working channel.
    pub const USERD_SIZE: u64 = 0x400;
    /// tinygrad: `errorNotifierMem = {base 0, size 0xecc, addressSpace 0}`.
    pub const ERROR_NOTIFIER_SIZE: u64 = 0xecc;
    /// Our choice (tinygrad uses 0x10000): 8 KiB of ring, USERD page-aligned after it.
    pub const ENTRIES: u32 = 0x400;
}

impl WorkChannelSetup {
    /// Where USERD starts inside the buffer: right after the ring.
    pub fn userd_offset(&self) -> u64 {
        self.entries as u64 * 8
    }
    /// Bytes the ring + USERD buffer must have.
    pub fn buffer_size(entries: u32) -> u64 {
        (entries as u64 * 8 + work_channel::USERD_SIZE).next_multiple_of(0x1000)
    }
}

/// The low 32 bits of a PA, as tinygrad puts them in the handle fields.
/// GSP-RM does not resolve these handles on its side (RM 570.144
/// `kernel_channel.c`: with `RMCFG_FEATURE_PLATFORM_GSP` and a channel not
/// owned by GSP, the error context is not looked up and USERD is described
/// from `userdMem`); only "non-zero" matters. Zero is refused.
fn handle_marker(pa: u64) -> GpuResult<u32> {
    match pa as u32 {
        0 => Err(GpuError::InvalidArgument(
            "canal: adresa nu poate sta intr-un handle (32 de biti zero)",
        )),
        h => Ok(h),
    }
}

/// I9e: `NV_CHANNEL_ALLOC_PARAMS` for a working channel whose parent is a
/// channel group. RM 570.144 `kchannelConstruct` (MIT, read as the
/// specification): a TSG channel names a context share and no VA space
/// (both = `INVALID_ARGUMENT`), the channel type must be physical
/// (`flags` = 0 here), `engineType` 0 means "the TSG's engine". The memory
/// descriptors are what GSP-RM uses instead of allocating (tinygrad's
/// values: instance 4 KiB, RAMFC 0x200 at its start, method buffer 0x5000,
/// USERD 0x400 after the ring, error notifier {0, 0xecc, 0}).
pub fn work_channel_params(c: &WorkChannelSetup) -> GpuResult<Vec<u8>> {
    use golden_channel as g;
    if c.entries < 2 || !c.entries.is_power_of_two() {
        return Err(GpuError::InvalidArgument(
            "canal: numarul de intrari GPFIFO nu e putere a lui 2",
        ));
    }
    if c.ring_va == 0 || !c.ring_va.is_multiple_of(0x1000) || !c.ring_pa.is_multiple_of(0x1000) {
        return Err(GpuError::InvalidArgument(
            "canal: adresa GPFIFO lipsa sau nealiniata",
        ));
    }
    if c.ctxshare == 0 {
        return Err(GpuError::InvalidArgument(
            "canal: fara context share (grupul cere unul)",
        ));
    }
    for pa in [c.inst_pa, c.mthd_pa] {
        if pa == 0 || !pa.is_multiple_of(0x1000) {
            return Err(GpuError::InvalidArgument(
                "canal: instanta sau bufferul de metode nealiniat",
            ));
        }
    }
    type C = r::NV_CHANNEL_ALLOC_PARAMS;
    let buffer = handle_marker(c.ring_pa)?;
    let error = handle_marker(c.notifier_pa)?;
    let mut b = alloc::vec![0u8; size_of::<C>()];
    put_u32(&mut b, offset_of!(C, hObjectError), error);
    put_u32(&mut b, offset_of!(C, hObjectBuffer), buffer);
    put_u64(&mut b, offset_of!(C, gpFifoOffset), c.ring_va);
    put_u32(&mut b, offset_of!(C, gpFifoEntries), c.entries);
    put_u32(&mut b, offset_of!(C, hContextShare), c.ctxshare);
    put_u32(&mut b, offset_of!(C, hUserdMemory), buffer); // [0]
    put_u64(&mut b, offset_of!(C, userdOffset), c.userd_offset()); // [0]
    put_memdesc(
        &mut b,
        offset_of!(C, instanceMem),
        &MemDesc::vidmem(c.inst_pa, g::INSTANCE_SIZE),
    );
    put_memdesc(
        &mut b,
        offset_of!(C, userdMem),
        &MemDesc::vidmem(c.ring_pa + c.userd_offset(), work_channel::USERD_SIZE),
    );
    put_memdesc(
        &mut b,
        offset_of!(C, ramfcMem),
        &MemDesc::vidmem(c.inst_pa, g::RAMFC_SIZE),
    );
    put_memdesc(
        &mut b,
        offset_of!(C, mthdbufMem),
        &MemDesc::vidmem(c.mthd_pa, g::METHOD_BUFFER_SIZE),
    );
    put_memdesc(
        &mut b,
        offset_of!(C, errorNotifierMem),
        &MemDesc {
            base: 0,
            size: work_channel::ERROR_NOTIFIER_SIZE,
            address_space: 0,
            cache_attrib: 0,
        },
    );
    Ok(b)
}

/// `NVC36F_CTRL_CMD_GPFIFO_GET_WORK_SUBMIT_TOKEN_PARAMS` request
/// (tinygrad sends `workSubmitToken = -1`).
pub fn work_submit_token_request() -> Vec<u8> {
    type P = r::NVC36F_CTRL_CMD_GPFIFO_GET_WORK_SUBMIT_TOKEN_PARAMS;
    let mut b = alloc::vec![0u8; size_of::<P>()];
    put_u32(&mut b, offset_of!(P, workSubmitToken), u32::MAX);
    b
}

/// `NV_CTRL_VF_DOORBELL` (RM 570.144 `swref/published/ampere/ga100/dev_ctrl.h`,
/// MIT): `VECTOR` = bits 11:0 (the channel id), `RUNLIST_ID` = bits 22:16.
pub const DOORBELL_VECTOR_MASK: u32 = 0xfff;
pub const DOORBELL_RUNLIST_SHIFT: u32 = 16;
pub const DOORBELL_RUNLIST_MASK: u32 = 0x7f;

/// The doorbell value for a channel. On GSP, RM's token is the channel id
/// only (`kfifoGenerateWorkSubmitTokenHal_GA100`: under
/// `RMCFG_FEATURE_PLATFORM_GSP` it returns the internal token); CPU-RM adds
/// the runlist (`_CTRL_VF_DOORBELL_RUNLIST_ID`), and so does tinygrad
/// (`| runlist << 16`). A reply with bits outside `VECTOR`, or a runlist
/// that does not fit, is an error — never rung.
pub fn doorbell_token(gsp_token: u32, runlist: u32) -> GpuResult<u32> {
    if gsp_token & !DOORBELL_VECTOR_MASK != 0 || gsp_token == u32::MAX {
        return Err(GpuError::InvalidArgument(
            "jetonul soneriei: GSP-RM a raspuns cu altceva decat un canal",
        ));
    }
    if runlist > DOORBELL_RUNLIST_MASK {
        return Err(GpuError::InvalidArgument(
            "jetonul soneriei: runlist prea mare",
        ));
    }
    Ok(gsp_token | runlist << DOORBELL_RUNLIST_SHIFT)
}

/// The channel id in GSP-RM's reply to the token request.
pub fn parse_work_submit_token(p: &[u8]) -> GpuResult<u32> {
    type P = r::NVC36F_CTRL_CMD_GPFIFO_GET_WORK_SUBMIT_TOKEN_PARAMS;
    if p.len() != size_of::<P>() {
        return Err(GpuError::InvalidArgument(
            "jetonul soneriei: lungime gresita",
        ));
    }
    Ok(get_u32(p, offset_of!(P, workSubmitToken)))
}

/// `NVA06C_CTRL_GPFIFO_SCHEDULE_PARAMS` (= the `A06F` one): enable, submit.
pub fn schedule_params(enable: bool) -> Vec<u8> {
    type P = r::NVA06F_CTRL_GPFIFO_SCHEDULE_PARAMS;
    let mut b = alloc::vec![0u8; size_of::<P>()];
    b[offset_of!(P, bEnable)] = enable as u8;
    b
}

/// `NV2080_CTRL_FIFO_GET_DEVICE_INFO_TABLE_PARAMS` request (first page).
pub fn device_info_request() -> Vec<u8> {
    alloc::vec![0u8; size_of::<r::NV2080_CTRL_FIFO_GET_DEVICE_INFO_TABLE_PARAMS>()]
}

/// `engineData[]` indices (`ENGINE_INFO_TYPE_*`, `kernel/gpu/fifo/engine_info.h`
/// 570.144, MIT; the enum is ABI: "THINK BEFORE CHANGING ENUM ORDER").
pub const ENGINE_INFO_RM_ENGINE_TYPE: usize = 2;
pub const ENGINE_INFO_RUNLIST: usize = 3;

/// (RM engine type, runlist) per device-info entry.
pub fn parse_device_info(p: &[u8]) -> GpuResult<Vec<(u32, u32)>> {
    type T = r::NV2080_CTRL_FIFO_GET_DEVICE_INFO_TABLE_PARAMS;
    type E = r::NV2080_CTRL_FIFO_DEVICE_ENTRY;
    if p.len() != size_of::<T>() {
        return Err(GpuError::InvalidArgument("device info: lungime gresita"));
    }
    let n = get_u32(p, offset_of!(T, numEntries)) as usize;
    if n > r::NV2080_CTRL_FIFO_GET_DEVICE_INFO_TABLE_MAX_ENTRIES as usize {
        return Err(GpuError::InvalidArgument("device info: prea multe intrari"));
    }
    let data = offset_of!(E, engineData);
    Ok((0..n)
        .map(|i| {
            let e = offset_of!(T, entries) + i * size_of::<E>() + data;
            (
                get_u32(p, e + 4 * ENGINE_INFO_RM_ENGINE_TYPE),
                get_u32(p, e + 4 * ENGINE_INFO_RUNLIST),
            )
        })
        .collect())
}

/// One level of the page tables covering the reserved VA range.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PdeLevel {
    pub phys: u64,
    pub size: u64,
    pub page_shift: u8,
    /// 1 = video memory (tinygrad).
    pub aperture: u32,
}

/// `NV90F1_CTRL_VASPACE_COPY_SERVER_RESERVED_PDES_PARAMS`: tells GSP-RM where
/// the driver's page tables for the reserved VA range are (tinygrad reserves
/// 512 MiB and passes 3 levels).
pub fn reserved_pdes_params(va_lo: u64, size: u64, levels: &[PdeLevel]) -> GpuResult<Vec<u8>> {
    type P = r::NV90F1_CTRL_VASPACE_COPY_SERVER_RESERVED_PDES_PARAMS;
    type L = r::NV90F1_CTRL_VASPACE_COPY_SERVER_RESERVED_PDES_PARAMS__bindgen_ty_1;
    let max = r::GMMU_FMT_MAX_LEVELS as usize;
    if levels.is_empty() || levels.len() > max || size == 0 || !va_lo.is_multiple_of(size) {
        return Err(GpuError::InvalidArgument(
            "PDE rezervate: niveluri sau interval gresit",
        ));
    }
    let mut b = alloc::vec![0u8; size_of::<P>()];
    put_u64(&mut b, offset_of!(P, pageSize), size);
    put_u64(&mut b, offset_of!(P, virtAddrLo), va_lo);
    put_u64(&mut b, offset_of!(P, virtAddrHi), va_lo + size - 1);
    put_u32(&mut b, offset_of!(P, numLevelsToCopy), levels.len() as u32);
    for (i, l) in levels.iter().enumerate() {
        let at = offset_of!(P, levels) + i * size_of::<L>();
        put_u64(&mut b, at + offset_of!(L, physAddress), l.phys);
        put_u64(&mut b, at + offset_of!(L, size), l.size);
        put_u32(&mut b, at + offset_of!(L, aperture), l.aperture);
        b[at + offset_of!(L, pageShift)] = l.page_shift;
    }
    Ok(b)
}

/// `NV_VASPACE_ALLOCATION_FLAGS_*` from `nvos.h` (570.144). Written by hand:
/// the header defines them as `BIT(n)`, which bindgen cannot evaluate.
pub mod vaspace_flags {
    pub const SHARED_MANAGEMENT: u32 = 1 << 2;
    pub const IS_EXTERNALLY_OWNED: u32 = 1 << 3;
    pub const ENABLE_PAGE_FAULTING: u32 = 1 << 6;
}

/// I9c: the VA space of the driver's working client. tinygrad (`ops_nv.py`
/// `NVDevice.__init__`, MIT, 9cf7829a6) asks for this range and these flags;
/// RM 570.144 (`gpu_vaspace.c` `gvaspaceExternalRootDirCommit`, MIT) accepts
/// `SET_PAGE_DIRECTORY` only on a VA space that is `IS_EXTERNALLY_OWNED` (or
/// `SHARED_MANAGEMENT`). The range values themselves are DEDUS.
pub const USER_VA_BASE: u64 = 0x1000;
pub const USER_VA_SIZE: u64 = 0x1_ffff_fb00_0000;

/// `NV_VASPACE_ALLOCATION_PARAMETERS` for the working client: page tables
/// owned by the driver (externally owned), page faulting on, as tinygrad.
pub fn user_vaspace_params() -> Vec<u8> {
    type P = r::NV_VASPACE_ALLOCATION_PARAMETERS;
    let mut b = alloc::vec![0u8; size_of::<P>()];
    put_u32(
        &mut b,
        offset_of!(P, flags),
        vaspace_flags::IS_EXTERNALLY_OWNED | vaspace_flags::ENABLE_PAGE_FAULTING,
    );
    put_u64(&mut b, offset_of!(P, vaBase), USER_VA_BASE);
    put_u64(&mut b, offset_of!(P, vaSize), USER_VA_SIZE);
    b
}

/// `pasid` tinygrad sends (no ATS on this VA space, so RM ignores it). DEDUS.
pub const NO_PASID: u32 = 0xffff_ffff;

/// A root table GSP-RM can be told about: a non-zero, 4 KiB-aligned VRAM
/// address (the instance block holds it in 4 KiB units).
pub fn check_root(root_pa: u64) -> GpuResult<()> {
    if root_pa == 0 || !root_pa.is_multiple_of(0x1000) || root_pa >= crate::mmu::PA_LIMIT {
        return Err(GpuError::InvalidArgument(
            "SET_PAGE_DIRECTORY: radacina nu e o adresa VRAM aliniata la 4 KiB",
        ));
    }
    Ok(())
}

/// Payload of the `SET_PAGE_DIRECTORY` RPC (`rpc_set_page_directory_v1E_05`
/// with `NV0080_CTRL_DMA_SET_PAGE_DIRECTORY_PARAMS_v1E_05`, generated): tells
/// GSP-RM that the VA space `vaspace` of `device` uses the driver's root
/// table (PD3) at `root_pa` in video memory, `entries` entries, for all its
/// channels (`ALL_CHANNELS`, as tinygrad; subdevice 1 = the only GPU).
/// Refused before anything is sent: a root that fails [`check_root`], or no
/// entries.
pub fn set_page_directory_rpc(
    client: u32,
    device: u32,
    vaspace: u32,
    root_pa: u64,
    entries: u32,
) -> GpuResult<Vec<u8>> {
    type R = r::rpc_set_page_directory_v1E_05;
    type P = r::NV0080_CTRL_DMA_SET_PAGE_DIRECTORY_PARAMS_v1E_05;
    check_root(root_pa)?;
    if entries == 0 || vaspace == 0 {
        return Err(GpuError::InvalidArgument(
            "SET_PAGE_DIRECTORY: fara intrari sau fara spatiu de adrese",
        ));
    }
    // flags: APERTURE (1:0) = VIDMEM, ALL_CHANNELS (bit 3) = TRUE (ctrl0080dma.h).
    let flags = r::NV0080_CTRL_DMA_SET_PAGE_DIRECTORY_FLAGS_APERTURE_VIDMEM
        | r::NV0080_CTRL_DMA_SET_PAGE_DIRECTORY_FLAGS_ALL_CHANNELS_TRUE << 3;
    let mut b = alloc::vec![0u8; size_of::<R>()];
    put_u32(&mut b, offset_of!(R, hClient), client);
    put_u32(&mut b, offset_of!(R, hDevice), device);
    put_u32(&mut b, offset_of!(R, pasid), NO_PASID);
    let p = offset_of!(R, params);
    put_u64(&mut b, p + offset_of!(P, physAddress), root_pa);
    put_u32(&mut b, p + offset_of!(P, numEntries), entries);
    put_u32(&mut b, p + offset_of!(P, flags), flags);
    put_u32(&mut b, p + offset_of!(P, hVASpace), vaspace);
    put_u32(&mut b, p + offset_of!(P, chId), 0);
    put_u32(&mut b, p + offset_of!(P, subDeviceId), 1);
    put_u32(&mut b, p + offset_of!(P, pasid), NO_PASID);
    Ok(b)
}

/// I9d: `NV_CHANNEL_GROUP_ALLOCATION_PARAMETERS` for the working client's
/// channel group (TSG): the graphics engine (GR0, the only one without MIG,
/// RM 570.144 `kernel_channel_group_api.c`), and — unlike tinygrad, which
/// leaves it 0 — the VA space named explicitly, so RM does not fall back to
/// a device default VA space that does not use our page tables.
/// No error notifiers (as tinygrad).
pub fn channel_group_params(vaspace: u32) -> GpuResult<Vec<u8>> {
    type P = r::NV_CHANNEL_GROUP_ALLOCATION_PARAMETERS;
    if vaspace == 0 {
        return Err(GpuError::InvalidArgument(
            "grupul de canale: fara spatiu de adrese",
        ));
    }
    let mut b = alloc::vec![0u8; size_of::<P>()];
    put_u32(&mut b, offset_of!(P, hVASpace), vaspace);
    put_u32(
        &mut b,
        offset_of!(P, engineType),
        r::NV2080_ENGINE_TYPE_GRAPHICS,
    );
    Ok(b)
}

/// `NV_CTXSHARE_ALLOCATION_FLAGS_SUBCONTEXT_*` (generated).
pub mod subcontext {
    use super::r;
    pub const SYNC: u32 = r::NV_CTXSHARE_ALLOCATION_FLAGS_SUBCONTEXT_SYNC;
    pub const ASYNC: u32 = r::NV_CTXSHARE_ALLOCATION_FLAGS_SUBCONTEXT_ASYNC;
    pub const SPECIFIED: u32 = r::NV_CTXSHARE_ALLOCATION_FLAGS_SUBCONTEXT_SPECIFIED;
    pub const ASYNC_PREFER_LOWER: u32 =
        r::NV_CTXSHARE_ALLOCATION_FLAGS_SUBCONTEXT_ASYNC_PREFER_LOWER;
}

/// Subcontexts (VEIDs) per channel group we accept from GSP-RM: 64 on
/// Volta and later. DEDUS (RM queries it: `MAX_SUBCONTEXT_PER_GROUP`).
pub const MAX_SUBCONTEXTS: u32 = 64;

/// `NV_CTXSHARE_ALLOCATION_PARAMETERS`: the context share's VA space and
/// how its subcontext is chosen (tinygrad: the working VA space, `ASYNC`).
pub fn ctxshare_params(vaspace: u32, flags: u32) -> GpuResult<Vec<u8>> {
    type P = r::NV_CTXSHARE_ALLOCATION_PARAMETERS;
    if vaspace == 0 || flags > subcontext::ASYNC_PREFER_LOWER || flags == subcontext::SPECIFIED {
        // SPECIFIED is for NVIDIA's verification only (nvos.h).
        return Err(GpuError::InvalidArgument(
            "context share: spatiu de adrese lipsa sau mod necunoscut",
        ));
    }
    let mut b = alloc::vec![0u8; size_of::<P>()];
    put_u32(&mut b, offset_of!(P, hVASpace), vaspace);
    put_u32(&mut b, offset_of!(P, flags), flags);
    Ok(b)
}

/// The subcontext id GSP-RM chose (`subctxId` in the returned parameters,
/// bits 30:0). The other fields must come back as sent; an id outside the
/// group is an error, never used.
pub fn parse_ctxshare_reply(sent: &[u8], got: &[u8]) -> GpuResult<u32> {
    type P = r::NV_CTXSHARE_ALLOCATION_PARAMETERS;
    if got.len() != size_of::<P>() || sent.len() != got.len() {
        return Err(GpuError::InvalidArgument(
            "context share: raspuns de alta lungime",
        ));
    }
    for o in [offset_of!(P, hVASpace), offset_of!(P, flags)] {
        if get_u32(got, o) != get_u32(sent, o) {
            return Err(GpuError::InvalidArgument(
                "context share: raspunsul are alti parametri",
            ));
        }
    }
    let id = get_u32(got, offset_of!(P, subctxId)) & 0x7fff_ffff;
    if id >= MAX_SUBCONTEXTS {
        return Err(GpuError::InvalidArgument(
            "context share: subcontext in afara grupului",
        ));
    }
    Ok(id)
}

/// `NV2080_CTRL_INTERNAL_STATIC_KGR_GET_CONTEXT_BUFFERS_INFO_PARAMS` request.
pub fn ctx_buffers_info_request() -> Vec<u8> {
    alloc::vec![0u8; size_of::<r::NV2080_CTRL_INTERNAL_STATIC_KGR_GET_CONTEXT_BUFFERS_INFO_PARAMS>()]
}

/// Number of `ENGINE_ID_*` context-buffer kinds (generated).
pub const CTX_ENGINE_IDS: usize =
    r::NV0080_CTRL_FIFO_GET_ENGINE_CONTEXT_PROPERTIES_ENGINE_ID_COUNT as usize;

/// (size, alignment) of each context-buffer kind for GR0 (`[0]` of the
/// per-engine array).
pub fn parse_ctx_buffers_info(p: &[u8]) -> GpuResult<[(u32, u32); CTX_ENGINE_IDS]> {
    type I = r::NV2080_CTRL_INTERNAL_ENGINE_CONTEXT_BUFFER_INFO;
    if p.len() != size_of::<r::NV2080_CTRL_INTERNAL_STATIC_KGR_GET_CONTEXT_BUFFERS_INFO_PARAMS>() {
        return Err(GpuError::InvalidArgument(
            "context buffers info: lungime gresita",
        ));
    }
    let mut out = [(0u32, 0u32); CTX_ENGINE_IDS];
    for (i, o) in out.iter_mut().enumerate() {
        let at = i * size_of::<I>();
        *o = (
            get_u32(p, at + offset_of!(I, size)),
            get_u32(p, at + offset_of!(I, alignment)),
        );
    }
    Ok(out)
}

/// One `NV2080_CTRL_GPU_PROMOTE_CTX_BUFFER_ENTRY`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PromoteEntry {
    pub buffer_id: u16,
    pub gpu_va: u64,
    pub gpu_pa: u64,
    pub size: u64,
    pub phys_attr: u32,
    pub initialize: bool,
    pub nonmapped: bool,
}

/// `NV2080_CTRL_GPU_PROMOTE_CTX_PARAMS`.
pub fn promote_params(
    engine: u32,
    h_chan_client: u32,
    h_object: u32,
    entries: &[PromoteEntry],
) -> GpuResult<Vec<u8>> {
    type P = r::NV2080_CTRL_GPU_PROMOTE_CTX_PARAMS;
    type E = r::NV2080_CTRL_GPU_PROMOTE_CTX_BUFFER_ENTRY;
    if entries.is_empty() || entries.len() > r::NV2080_CTRL_GPU_PROMOTE_CONTEXT_MAX_ENTRIES as usize
    {
        return Err(GpuError::InvalidArgument("PROMOTE_CTX: 1..16 intrari"));
    }
    let mut b = alloc::vec![0u8; size_of::<P>()];
    put_u32(&mut b, offset_of!(P, engineType), engine);
    put_u32(&mut b, offset_of!(P, hChanClient), h_chan_client);
    put_u32(&mut b, offset_of!(P, hObject), h_object);
    put_u32(&mut b, offset_of!(P, entryCount), entries.len() as u32);
    for (i, e) in entries.iter().enumerate() {
        let at = offset_of!(P, promoteEntry) + i * size_of::<E>();
        put_u64(&mut b, at + offset_of!(E, gpuPhysAddr), e.gpu_pa);
        put_u64(&mut b, at + offset_of!(E, gpuVirtAddr), e.gpu_va);
        put_u64(&mut b, at + offset_of!(E, size), e.size);
        put_u32(&mut b, at + offset_of!(E, physAttr), e.phys_attr);
        b[at + offset_of!(E, bufferId)..][..2].copy_from_slice(&e.buffer_id.to_le_bytes());
        b[at + offset_of!(E, bInitialize)] = e.initialize as u8;
        b[at + offset_of!(E, bNonmapped)] = e.nonmapped as u8;
    }
    Ok(b)
}

/// Reads back the entries of a promote block (used by tests and by the log
/// comparison with the tinygrad probe).
pub fn parse_promote(p: &[u8]) -> GpuResult<Vec<PromoteEntry>> {
    type P = r::NV2080_CTRL_GPU_PROMOTE_CTX_PARAMS;
    type E = r::NV2080_CTRL_GPU_PROMOTE_CTX_BUFFER_ENTRY;
    if p.len() != size_of::<P>() {
        return Err(GpuError::InvalidArgument("PROMOTE_CTX: lungime gresita"));
    }
    let n = get_u32(p, offset_of!(P, entryCount)) as usize;
    if n > r::NV2080_CTRL_GPU_PROMOTE_CONTEXT_MAX_ENTRIES as usize {
        return Err(GpuError::InvalidArgument("PROMOTE_CTX: prea multe intrari"));
    }
    Ok((0..n)
        .map(|i| {
            let at = offset_of!(P, promoteEntry) + i * size_of::<E>();
            PromoteEntry {
                gpu_pa: get_u64(p, at + offset_of!(E, gpuPhysAddr)),
                gpu_va: get_u64(p, at + offset_of!(E, gpuVirtAddr)),
                size: get_u64(p, at + offset_of!(E, size)),
                phys_attr: get_u32(p, at + offset_of!(E, physAttr)),
                buffer_id: u16::from_le_bytes([
                    p[at + offset_of!(E, bufferId)],
                    p[at + offset_of!(E, bufferId) + 1],
                ]),
                initialize: p[at + offset_of!(E, bInitialize)] != 0,
                nonmapped: p[at + offset_of!(E, bNonmapped)] != 0,
            }
        })
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The generated layout agrees with the numbers written by hand in the
    /// independent model (`gpu_sim::fake_rm`) — two readings of the headers.
    #[test]
    fn generated_layouts_match_the_independent_model() {
        use gpu_sim::fake_rm::{class as fc, cmd as fcmd, size as fs};
        assert_eq!(
            [
                class::ROOT,
                class::DEVICE,
                class::SUBDEVICE,
                class::VASPACE,
                class::CHANNEL_GPFIFO,
                class::COMPUTE,
                class::DMA_COPY
            ],
            [
                fc::ROOT,
                fc::DEVICE,
                fc::SUBDEVICE,
                fc::VASPACE,
                fc::CHANNEL_GPFIFO,
                fc::COMPUTE,
                fc::DMA_COPY
            ]
        );
        assert_eq!(
            [
                cmd::GET_DEVICE_INFO_TABLE,
                cmd::KGR_GET_CONTEXT_BUFFERS_INFO,
                cmd::PROMOTE_CTX,
                cmd::COPY_SERVER_RESERVED_PDES
            ],
            [
                fcmd::GET_DEVICE_INFO_TABLE,
                fcmd::KGR_GET_CONTEXT_BUFFERS_INFO,
                fcmd::PROMOTE_CTX,
                fcmd::COPY_SERVER_RESERVED_PDES
            ]
        );
        assert_eq!(
            [
                root_params().len(),
                device_params(1).len(),
                subdevice_params().len(),
                vaspace_params().len()
            ],
            [fs::ROOT, fs::DEVICE, fs::SUBDEVICE, fs::VASPACE]
        );
        let ch = channel_params(&ChannelSetup::golden(0x1000, 0x2000, 7, 0x3000, 0x4000)).unwrap();
        assert_eq!(ch.len(), fs::CHANNEL);
        assert_eq!(device_info_request().len(), fs::DEVICE_INFO);
        // I9e: the token and schedule controls.
        assert_eq!(
            [cmd::WORK_SUBMIT_TOKEN, cmd::TSG_SCHEDULE],
            [fcmd::WORK_SUBMIT_TOKEN, fcmd::TSG_SCHEDULE]
        );
        assert_eq!(
            [
                work_submit_token_request().len(),
                schedule_params(true).len()
            ],
            [fs::WORK_SUBMIT_TOKEN, fs::TSG_SCHEDULE]
        );
        assert_eq!(ctx_buffers_info_request().len(), fs::KGR_INFO);
        assert_eq!(
            reserved_pdes_params(
                0,
                1 << 29,
                &[PdeLevel {
                    phys: 0x1000,
                    size: 8,
                    page_shift: 47,
                    aperture: 1
                }]
            )
            .unwrap()
            .len(),
            fs::RESERVED_PDES
        );
        let e = PromoteEntry {
            buffer_id: 0,
            gpu_va: 1,
            gpu_pa: 0x1000,
            size: 1,
            phys_attr: 4,
            initialize: true,
            nonmapped: false,
        };
        assert_eq!(promote_params(1, 2, 3, &[e]).unwrap().len(), fs::PROMOTE);
        assert_eq!((ALLOC_HDR, CONTROL_HDR), (32, 24));
        assert_eq!(CTX_ENGINE_IDS, 26);
    }

    /// I9c: the SET_PAGE_DIRECTORY message and the working client's VA
    /// space, at the offsets the model reads by hand.
    #[test]
    fn page_directory_fields_land_where_the_model_reads_them() {
        use gpu_sim::fake_rm::{FN_SET_PAGE_DIRECTORY, size as fs, va_flags as fv};
        assert_eq!(
            super::super::rpc::function::SET_PAGE_DIRECTORY,
            FN_SET_PAGE_DIRECTORY
        );
        let b = set_page_directory_rpc(0xc100_0000, 0xcf00_0007, 0xcf00_0009, 0x7_0000_0000, 4)
            .unwrap();
        assert_eq!(b.len(), fs::SET_PAGE_DIRECTORY);
        assert_eq!(
            (get_u32(&b, 0), get_u32(&b, 4), get_u32(&b, 8)),
            (0xc100_0000, 0xcf00_0007, NO_PASID)
        );
        assert_eq!(
            (get_u64(&b, 16), get_u32(&b, 24), get_u32(&b, 28)),
            (0x7_0000_0000, 4, 0x8)
        );
        assert_eq!(
            (
                get_u32(&b, 32),
                get_u32(&b, 36),
                get_u32(&b, 40),
                get_u32(&b, 44)
            ),
            (0xcf00_0009, 0, 1, NO_PASID)
        );
        assert_eq!(cmd_set_page_directory(), 0x80_1813);
        let v = user_vaspace_params();
        assert_eq!(v.len(), fs::VASPACE);
        assert_eq!(get_u32(&v, 4), fv::IS_EXTERNALLY_OWNED | 1 << 6);
        assert_eq!(
            (get_u64(&v, 8), get_u64(&v, 40)),
            (USER_VA_SIZE, USER_VA_BASE)
        );
        assert_eq!(
            (
                vaspace_flags::SHARED_MANAGEMENT,
                vaspace_flags::IS_EXTERNALLY_OWNED
            ),
            (fv::SHARED_MANAGEMENT, fv::IS_EXTERNALLY_OWNED)
        );
        // Refused before anything is built.
        for root in [0, 0x1800, crate::mmu::PA_LIMIT] {
            assert!(set_page_directory_rpc(1, 2, 3, root, 4).is_err());
        }
        assert!(set_page_directory_rpc(1, 2, 3, 0x1000, 0).is_err());
        assert!(set_page_directory_rpc(1, 2, 0, 0x1000, 4).is_err());
    }

    /// The control number of the same operation, for the record (the RPC is
    /// used, not the control): `NV0080_CTRL_CMD_DMA_SET_PAGE_DIRECTORY`.
    fn cmd_set_page_directory() -> u32 {
        r::NV0080_CTRL_CMD_DMA_SET_PAGE_DIRECTORY
    }

    #[test]
    fn golden_channel_fields_land_where_the_model_reads_them() {
        let c = ChannelSetup::golden(0x10_0000, 0x7f_0000, 0xcf00_0003, 0x7e_0000, 0x7d_0000);
        let b = channel_params(&c).unwrap();
        // Offsets as written by hand in gpu_sim::fake_rm.
        assert_eq!(get_u64(&b, 8), 0x10_0000);
        assert_eq!(get_u32(&b, 16), 32);
        assert_eq!(get_u32(&b, 20), 0x0020_0320);
        assert_eq!(get_u32(&b, 28), 0xcf00_0003);
        assert_eq!(get_u64(&b, 64), 0x100);
        assert_eq!((get_u32(&b, 128), get_u32(&b, 132)), (1, 3));
        assert_eq!(
            (get_u64(&b, 144), get_u64(&b, 152), get_u32(&b, 160)),
            (0x7e_0000, 0x1000, 2)
        );
        assert_eq!((get_u64(&b, 168), get_u64(&b, 176)), (0x7f_0100, 0x20));
        assert_eq!((get_u64(&b, 192), get_u64(&b, 200)), (0x7e_0000, 0x200));
        assert_eq!((get_u64(&b, 216), get_u64(&b, 224)), (0x7d_0000, 0x5000));
        assert_eq!(get_u32(&b, 244), 0x1a);
        // Impossible channels are refused before anything is sent.
        let mut bad = c;
        bad.gpfifo_entries = 33;
        assert!(channel_params(&bad).is_err());
        bad = c;
        bad.gpfifo_va = 0x10_0008;
        assert!(channel_params(&bad).is_err());
    }

    #[test]
    fn replies_with_an_rm_error_are_errors() {
        let sent = encode_alloc(1, 2, 3, class::DEVICE, &device_params(1));
        let mut reply = sent.clone();
        assert_eq!(check_alloc_reply(&sent, &reply).unwrap(), device_params(1));
        put_u32(&mut reply, 16, 0x36); // NV_ERR_INVALID_OBJECT_PARENT
        assert_eq!(
            check_alloc_reply(&sent, &reply),
            Err(GpuError::HardwareFault { code: 0x36 })
        );
        reply = sent.clone();
        put_u32(&mut reply, 8, 4); // answer for another object
        assert!(check_alloc_reply(&sent, &reply).is_err());
        assert!(check_alloc_reply(&sent, &sent[..40]).is_err());
        let c = encode_control(1, 5, cmd::PROMOTE_CTX, &[0; 8]);
        let mut cr = c.clone();
        put_u32(&mut cr, 12, 0x40);
        assert_eq!(
            check_control_reply(&c, &cr),
            Err(GpuError::HardwareFault { code: 0x40 })
        );
        put_u32(&mut cr, 12, 0);
        put_u32(&mut cr, 8, cmd::GET_DEVICE_INFO_TABLE);
        assert!(check_control_reply(&c, &cr).is_err());
    }

    #[test]
    fn promote_entries_round_trip() {
        let es = [
            PromoteEntry {
                buffer_id: 0,
                gpu_va: 0x20_0000,
                gpu_pa: 0x7000_0000,
                size: 0x4_2000,
                phys_attr: 4,
                initialize: true,
                nonmapped: false,
            },
            PromoteEntry {
                buffer_id: 10,
                gpu_va: 0,
                gpu_pa: 0x7010_0000,
                size: 0x3000,
                phys_attr: 4,
                initialize: true,
                nonmapped: true,
            },
            PromoteEntry {
                buffer_id: 3,
                gpu_va: 0x30_0000,
                gpu_pa: 0,
                size: 0,
                phys_attr: 0,
                initialize: false,
                nonmapped: false,
            },
        ];
        let b = promote_params(ENGINE_GR0, 0xc1e0_0004, 0xcf00_0004, &es).unwrap();
        assert_eq!(parse_promote(&b).unwrap(), es);
        assert!(promote_params(1, 1, 1, &[]).is_err());
        assert!(promote_params(1, 1, 1, &[es[0]; 17]).is_err());
    }
}
